package cz.lollywood.falloutak;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.*;

/**
 * Part 7, production (`07-PRODUCTION.md` §4, RULED 11-20 in Marek's rounds 1-3; the catalogue `07b-RECIPES.md`, generated by
 * {@code LollyWood-Lore/_tools/fallout_catalogue.py} into {@code data/recipes.json}, {@code buildings.json}, {@code itemtypes.json}).
 * Pure Java: the tests run it.
 * <ul>
 * <li>A recipe = TTRs in, TTRs out; some inputs are tools (they wear), some optional extras (×1.5 faster); a skill and its minimum;
 * a building of at least the recipe's tier (the tier caps what it makes); work hours at the minimum skill; days that must pass.</li>
 * <li>A building runs ONE job at a time with a crew of at most its slots (Marek: *"some building/production equipment may allow
 * more people"*); the automatic pick takes the best free workers for the skill (*"to pick from the group the best in this process
 * first"*), among every worker free in the base (round 2: *"your idea works"*); the players may change it.</li>
 * <li>Speed: each worker adds hours × his skill ÷ the minimum (at most ×4); the hours add up (round 1-2); an extra ×1.5.</li>
 * <li>Rarity: the lowest rarity among the inputs the recipe marks (round 2: *"recipe marks it"*), never rolled (round 1); only
 * perks and traits cheat it (Master Craftsman, Perfectionist).</li>
 * <li>Power and water: daily amounts, counted only on the days a building works; the kitchen and the automatic rooms every day
 * (round 1: *"Workshop does not need to work 24/7 ... But you do need kitchen as daily amount all the time."*).</li>
 * <li>Upkeep: a weekly project, fewer hours the higher the tier; a missed week costs its wear, by the tier, for the hours it ran and
 * stood idle ({@link Wear}, round 6: *"bigger tier, the less maintanance and the longer it lasts abandoned"*); at 0 the building
 * stops [mine]; the players manage the crews (round 4: *"Upkeep and crews - this is for players to manage."*).</li>
 * <li>A building works and makes less as its condition falls (round 4: *"it will get worse as condition worsens"*): {@link #efficiency}.
 * Its repair is slower the higher its tier (round 7: *"needed far less often, but far more time demanding"*): {@link #repairPerHour}.</li>
 * <li>Round 8 (Marek 11-21): the realistic water (*"Water: switch to the realistic version - yes"*): the kitchen's water a person fed,
 * the people's washing ({@link #washFrom}; round 9: the players' choice, the condensate first, clean water for the wounded,
 * {@link #unwashed}), the scrubbers' condensate, the filtration 400 l; a better Water stands in for a recipe's
 * water but never as good as the water it makes ({@link #topTier}).</li>
 * <li>Round 4 (Marek 11-20): the base makes PARTS, the items are ASSEMBLED from them when going out ({@code data/designs.json};
 * *"creating just the parts and the item assembled out of them when going out would work better"*): {@link Base#assemble}.</li>
 * <li>Round 5 (Marek 11-20): water of a lower tier from the store, the best first where it goes into the product (*"Lower-tier water -
 * yes, agreed."*), Tier I first where it only cools (*"workshop, kiln, still, scrubbers - I would make it rule that these use T1 water
 * first (reversed priority)."*): {@link #drawWater}; upkeep needs a tool of the building's tier (*"upkeep needs tools of the same
 * tier"*): {@link #upkeepTool}; the repair job on worn parts ({@link #REPAIRS}); the recipes ranked best first, the fully outdated
 * hidden (*"filter both by input and output and that the best recipes are shown on top, and probably hide these fully outdated"*):
 * {@link #rank}, {@link #outdatedBy}.</li>
 * </ul>
 */
final class Production {
    // ------------------------------------------------------------------ the catalogue
    static final class Ttr { String type = ""; int tier = 1, count = 1, rarity; boolean sets_rarity, tool, extra; }
    static final class Builds { String kind = ""; int tier = 1; }
    static final class Recipe {
        String id = "", name = "", building = "", skill = "", known = "start", research = "", better = "", note = "";
        /** A repair job's part type (round 5): it makes nothing, it mends one row of worn parts. "" = an ordinary recipe. */
        String repairs = "";
        int tier = 1, min;
        double hours, days;
        boolean harvest;
        List<Ttr> makes = new ArrayList<>(), inputs = new ArrayList<>();
        Builds builds;

        boolean atStart() { return "start".equals(known); }
    }
    static final class Kind {
        String kind = "", makes = "", upkeep_skill = "Crafting", note = "";
        /** Round 5: "product" = its water goes into what it makes (the best first, its tier caps the product), "cooling" = Tier I first. */
        String water_use = "";
        int slots = 1;
        double power, water;
        /**
         * Round 8 (Marek 11-21: *"Water: switch to the realistic version - yes"*): litres a person a day on top of {@code water} (the
         * kitchen's 3 a person fed), and the Tier II water a person a day the room gives (the scrubbers' condensate) [EXAMPLE].
         */
        double water_per_person, condensate;
        boolean daily, automatic;
        Map<String, Double> produces = new HashMap<>();
    }
    static final class Named { String name = "", id = ""; int tier = 1, rarity = 1; }
    static final class ItemType { String name = "", group = "", use = ""; boolean found_only; Map<String, String> tiers = new HashMap<>(); List<Named> items = new ArrayList<>(); }
    static final class Room { String kind = "", name = ""; int tier = 1; }
    /** One kind of part an assembly takes (of the item's tier unless the data says another). */
    static final class Part { String type = ""; int tier = 1, count = 1; }
    /**
     * An item assembled from parts when going out (round 4): no building, no skill, no time [mine]; the parts all at the item's rarity;
     * a batch gives {@code makes} items (rounds, arrows); an armour piece names its set and slot (05c).
     */
    static final class Design {
        String category = "", group = "", skill = "", name = "", slot = "", set = "";
        int tier = 1, rarity = 1, makes = 1;
        List<Part> parts = new ArrayList<>();

        boolean armour() { return slot != null && !slot.isEmpty(); }

        String key() { return category + "|" + name; }

        String label() { return name + " (" + Rules.roman(tier) + (rarity > 1 ? " R" + rarity : "") + ")"; }
    }
    static final class Category { String name = "", group = "", skill = "", note = ""; }
    /** An old type of 0.42.0 → its parts: {@code per} units give them (the store converts what it held). */
    static final class Legacy { List<Part> parts = new ArrayList<>(); int per = 1; }
    /** The repair job (round 5, `07b` §2) [mine, EXAMPLE]: the material and the skill per part type; the minimum, the hours a run, parts a run. */
    static final class RepairType { String material = "Metal", skill = "Crafting"; }
    static final class RepairRule { int min = 25, parts = 3; double hours = 1; String building = "Workbench"; Map<String, RepairType> types = new LinkedHashMap<>(); }

    static final Map<String, Recipe> RECIPES = new LinkedHashMap<>();
    static final Map<String, Kind> KINDS = new LinkedHashMap<>();
    static final Map<String, ItemType> TYPES = new LinkedHashMap<>();
    static final List<Room> SHELTER = new ArrayList<>();
    /** What is assembled, by {@link Design#key()}; the categories in the data's order; the old types. */
    static final Map<String, Design> DESIGNS = new LinkedHashMap<>();
    static final List<Category> CATEGORIES = new ArrayList<>();
    static final Map<String, Legacy> LEGACY = new LinkedHashMap<>();
    /** The repair job's rule, and one repair recipe per part type and tier (id {@code repair|<type>|<tier>}): not in the recipe lists. */
    static RepairRule REPAIR = new RepairRule();
    static final Map<String, Recipe> REPAIRS = new LinkedHashMap<>();
    /** Upkeep's tool (round 5): a Gear and tools of at least the building's tier. */
    static String UPKEEP_TOOL = "Gear and tools";
    /** The people's own water a day each (round 8): to drink (04 §3.9) and to wash (the cooling order, Tier I first) [EXAMPLE]. */
    static double DRINK = 2, WASH = 2;
    /**
     * A building's wear by its tier (round 6, Marek 11-20, verbatim: *"The buildings must have condition lost in some absolute number -
     * bigger tier, the less maintanance and the longer it lasts abandoned."* · *"players must not be forced out before first year"* ·
     * *"the reactor is made to last for decades without daily fixes"*) [the numbers EXAMPLE, mine]: the upkeep hours a week, the weeks
     * running round the clock from 100 % to 0 with no upkeep, the weeks standing idle (abandoned) from 100 % to 0, Tier I-IV.
     */
    static final class Wear {
        double[] upkeep_hours = {4, 3, 2, 1}, run_weeks = {26, 104, 260, 1300}, idle_weeks = {260, 780, 2080, 5200};
        /**
         * A worn or broken room's repair, % a crew hour with the tool of its tier, Tier I-IV (round 7, Marek 11-21, verbatim: *"Yes,
         * needed far less often, but far more time demanding."*) [the numbers EXAMPLE, mine]: 0 → 100 % in 25 / 50 / 100 / 250 crew hours.
         */
        double[] repair_per_hour = {4, 2, 1, 0.4};
    }
    static Wear WEAR = new Wear();

    /** % of condition a crew hour of repair gives back to a building of this tier (round 7). */
    static double repairPerHour(int tier) { return WEAR.repair_per_hour[Math.max(1, Math.min(4, tier)) - 1]; }

    /** % of condition an hour of running (or of standing idle) costs a building of this tier when its upkeep is missed. */
    static double wearPerHour(int tier, boolean running) {
        int i = Math.max(1, Math.min(4, tier)) - 1;
        return 100.0 / ((running ? WEAR.run_weeks[i] : WEAR.idle_weeks[i]) * 168);
    }
    /** Jury Rigging's materials (02c: *"repairs any item with any item of its tier"*) [mine: the materials' group]. */
    static final List<String> MATERIALS = List.of("Metal", "Wood", "Textile", "Stone and glass", "Chemicals", "Fuel", "Salvage");
    /** A Workshop does a Workbench's work of its tier [mine]. */
    static final Map<String, List<String>> SERVES = Map.of("Workshop", List.of("Workbench"));
    /** Pseudo-buildings: no room, any number of workers; a job there gets its own site (07b §3). */
    static final Set<String> SITES = Set.of("Base", "Outside");

    static {
        Gson g = new Gson();
        for (JsonElement e : rows("itemtypes")) { ItemType t = g.fromJson(e, ItemType.class); TYPES.put(t.name, t); }
        for (JsonElement e : rows("buildings")) { Kind k = g.fromJson(e, Kind.class); KINDS.put(k.kind, k); }
        for (JsonElement e : rows("recipes")) { Recipe r = g.fromJson(e, Recipe.class); RECIPES.put(r.id, r); }
        for (JsonElement e : rows("designs")) { Design d = g.fromJson(e, Design.class); DESIGNS.put(d.key(), d); }
        JsonObject o = whole("buildings");
        if (o != null && o.has("shelter")) for (JsonElement e : o.getAsJsonArray("shelter")) SHELTER.add(g.fromJson(e, Room.class));
        if (o != null && o.has("upkeep_tool")) UPKEEP_TOOL = o.get("upkeep_tool").getAsString();
        if (o != null && o.has("wear")) WEAR = g.fromJson(o.get("wear"), Wear.class);
        if (o != null && o.has("people_water")) {
            JsonObject pw = o.getAsJsonObject("people_water");
            if (pw.has("drink")) DRINK = pw.get("drink").getAsDouble();
            if (pw.has("wash")) WASH = pw.get("wash").getAsDouble();
        }
        o = whole("designs");
        if (o != null && o.has("categories")) for (JsonElement e : o.getAsJsonArray("categories")) CATEGORIES.add(g.fromJson(e, Category.class));
        if (o != null && o.has("legacy")) for (Map.Entry<String, JsonElement> e : o.getAsJsonObject("legacy").entrySet())
            LEGACY.put(e.getKey(), g.fromJson(e.getValue(), Legacy.class));
        if (o != null && o.has("repair")) REPAIR = g.fromJson(o.get("repair"), RepairRule.class);
        for (Map.Entry<String, RepairType> e : REPAIR.types.entrySet())
            for (int t = 1; t <= 4; t++) {
                Recipe r = new Recipe();
                r.id = "repair|" + e.getKey() + "|" + t;
                r.name = "Repair worn " + e.getKey() + " " + Rules.roman(t);
                r.building = REPAIR.building;
                r.tier = t;
                r.skill = e.getValue().skill;
                r.min = REPAIR.min;
                r.hours = REPAIR.hours;
                r.repairs = e.getKey();
                Ttr m = new Ttr();
                m.type = e.getValue().material;
                m.tier = t;
                r.inputs.add(m);
                r.note = "the repair kit's points by the best skill (Mr. Fixit x2) to each of up to " + REPAIR.parts + " worn parts a run; Jury Rigging: any material of the tier";
                REPAIRS.put(r.id, r);
            }
    }

    /** A recipe by its id: the catalogue's, or a repair job's. */
    static Recipe recipe(String id) {
        Recipe r = RECIPES.get(id);
        return r != null ? r : REPAIRS.get(id);
    }

    static Recipe repairRecipe(String type, int tier) { return REPAIRS.get("repair|" + type + "|" + tier); }

    private static JsonObject whole(String name) {
        try (InputStream in = Production.class.getResourceAsStream("/data/" + name + ".json")) {
            return in == null ? null : JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject();
        } catch (IOException e) {
            return null;
        }
    }

    static Design design(String category, String name) { return DESIGNS.get(category + "|" + name); }

    /** The design of an armour set's piece (05c's sets: every piece is one). */
    static Design piece(String set, String slot) {
        for (Design d : DESIGNS.values()) if (d.armour() && d.set.equals(set) && d.slot.equals(slot)) return d;
        return null;
    }

    static String partsText(Design d) {
        StringJoiner j = new StringJoiner(" + ");
        for (Part p : d.parts) j.add(p.count + " " + p.type + " " + Rules.roman(p.tier));
        return j + (d.rarity > 1 ? ", rarity " + d.rarity : "") + (d.makes > 1 ? " → " + d.makes : "");
    }

    private static List<JsonElement> rows(String name) {
        try (InputStream in = Production.class.getResourceAsStream("/data/" + name + ".json")) {
            if (in == null) return List.of();
            List<JsonElement> l = new ArrayList<>();
            JsonParser.parseReader(new InputStreamReader(in, StandardCharsets.UTF_8)).getAsJsonObject().getAsJsonArray("rows").forEach(l::add);
            return l;
        } catch (Exception e) {
            throw new IllegalStateException("data/" + name + ".json: " + e.getMessage(), e);
        }
    }

    static String ttr(Ttr t) {
        return (t.tool ? "tool: " : t.extra ? "extra: " : "") + t.count + " " + t.type + " " + Rules.roman(t.tier) + (t.rarity > 0 ? " R" + t.rarity : "") + (t.sets_rarity ? "*" : "");
    }

    static String makesText(Recipe r) {
        if (r.builds != null) return "a " + r.builds.kind + " (Tier " + Rules.roman(r.builds.tier) + ")";
        StringJoiner j = new StringJoiner(" + ");
        for (Ttr t : r.makes) j.add(t.count + " " + t.type + " " + Rules.roman(t.tier));
        return j.toString();
    }

    static String inputsText(Recipe r) {
        StringJoiner j = new StringJoiner(" + ");
        for (Ttr t : r.inputs) j.add(ttr(t));
        return j.length() == 0 ? "nothing" : j.toString();
    }

    // ------------------------------------------------------------------ the base's buildings and jobs
    static final class Job {
        String recipe = "";
        /** How many times (0 = until stopped) and how many are done. */
        int runs, done;
        /** The rarity the marked inputs are taken at (the output's, round 2). */
        int rarity = 1;
        /** This run: the work done (in hours at the minimum skill), when its inputs were taken (world hours), the extra in use. */
        double work, startedAt = -1;
        boolean inputsTaken, extra;
        int madeRarity = 1;
        /** The parts of an output a run could not give whole (a harvest × the factor, Salvager's +50 %): kept for the next run [mine]. */
        Map<String, Double> carry = new HashMap<>();
        /** The worst water tier this run took (round 5: a product room's product comes out no better; 5 = none taken). */
        int water = 5;
        /** Why it does not move now ("" = it works). */
        String waiting = "";
    }

    static final class Building {
        String id = "", kind = "", name = "";
        int tier = 1;
        double condition = 100, upkeepDone;
        /** The hours it worked this week (an automatic room every hour it stands, a job room the hours its crew worked the job). */
        double ranHours;
        long upkeepWeek = -1, chargedDay = -1;
        /** The condensate's fraction of a litre, carried to the next day (round 8). */
        double condensateCarry;
        /** The workers (their ids), at most the kind's slots. */
        List<String> crew = new ArrayList<>();
        Job job;
        /** A site for one job (Base, Outside): gone when the job ends. */
        boolean site;
        /** Today's water tier (5 = none); the week's upkeep waits for a tool (round 5), as of the last hour. */
        int waterTier = 5;
        transient boolean noTool;

        Kind kind() { return KINDS.get(kind); }

        String label() { return name + " (" + kind + ", Tier " + Rules.roman(tier) + ")"; }

        /** The upkeep hours a week, fewer the higher the tier (round 6) [EXAMPLE]. */
        double upkeepNeed() { return SITES.contains(kind) || "Dormitories".equals(kind) ? 0 : WEAR.upkeep_hours[Math.max(1, Math.min(4, tier)) - 1]; }

        int slots() { Kind k = kind(); return k == null ? 1 : k.slots; }
    }

    /** A worker: a PC (his own sheet) or a group's member (his group's statblock, part 6). */
    record Worker(String id, String label, Character sheet) {
        double skill(String name) { return sheet == null ? 0 : sheet.skill(name); }

        boolean perk(String name) { return sheet != null && (sheet.hasPerk(name) || hasTrait(name)); }

        private boolean hasTrait(String name) { for (Character.Feat f : sheet.traits) if (f.name().equals(name)) return true; return false; }
    }

    /** Who can work: the groups' members not busy otherwise and the PCs set to work in the base; the activity follows the crew. */
    interface Workforce {
        List<Worker> all();

        /** The worker's activity becomes this ("production", "gathering", or "" = idle again). */
        default void assign(String workerId, String activity) { }
    }

    final List<Building> buildings = new ArrayList<>();
    /** Recipes known beyond the start: research (part 8), a found schematic, the GM. */
    final Set<String> known = new TreeSet<>();
    /** The fields' yield in % (the nuclear autumn's failed harvests, part 1; the GM sets it). */
    double harvest = 100;
    long day = Long.MIN_VALUE;
    double powerUsed, waterUsed;
    /** The headcount of this pass of time (round 8: the kitchen's water a person fed, the washing, the condensate). */
    int people;
    /** The wounded among them (HP below their maximum): they wash with clean water first (round 9). */
    int wounded;
    /**
     * What the people may wash with (round 9, Marek 11-21: *"players can choose"* · *"that one can be selected, so choosing the
     * scrubber water and choosing T2 is the same answer"*): Tier I, Tier II (the scrubbers' condensate is Tier II) and Tier IV; the
     * clean water (the filtration's, the store's Tier III) always. [the defaults mine]
     */
    boolean washTier1 = false, washTier2 = true, washTier4 = false;
    /**
     * The base's people's average days since a wash (round 9, Marek 11-21: *"we should make rules for the penalities. At least it
     * should make infections and wounds/healing worse."*): each day (1 − the share washed) × (yesterday's + 1) [mine].
     */
    double unwashed;
    int nextId = 1;
    /** A Quartermaster among the base's workers (02c: "your faction's upkeep −20 %"), as of the last hour run. */
    transient boolean quartermaster;
    private transient Path file;

    // ------------------------------------------------------------------ what can be done
    boolean known(Recipe r) { return r != null && (r.atStart() || known.contains(r.id)); }

    /** Can this building run this recipe: its kind (or one it serves) and at least the recipe's tier. */
    static boolean fits(Building b, Recipe r) {
        if (b == null || r == null) return false;
        boolean kind = b.kind.equals(r.building) || SERVES.getOrDefault(b.kind, List.of()).contains(r.building);
        return kind && b.tier >= r.tier;
    }

    /** The known recipes a building can run, in the catalogue's order. */
    List<Recipe> recipesFor(Building b) {
        List<Recipe> l = new ArrayList<>();
        for (Recipe r : RECIPES.values()) if (known(r) && fits(b, r)) l.add(r);
        return l;
    }

    /** The known recipes that need no room (anywhere in the base, outside). */
    List<Recipe> siteRecipes(String kind) {
        List<Recipe> l = new ArrayList<>();
        for (Recipe r : RECIPES.values()) if (known(r) && r.building.equals(kind)) l.add(r);
        return l;
    }

    Building building(String id) {
        for (Building b : buildings) if (b.id.equals(id)) return b;
        return null;
    }

    Building build(String kind, int tier, String name) {
        Building b = new Building();
        b.id = "b" + nextId++;
        b.kind = kind;
        b.tier = Math.max(1, Math.min(4, tier));
        b.name = name == null || name.isBlank() ? kind : name;
        buildings.add(b);
        return b;
    }

    /** The shelter's seven rooms (RULED 11-20 round 2), once. Returns how many were added. */
    int shelter() {
        int n = 0;
        for (Room r : SHELTER) {
            boolean has = false;
            for (Building b : buildings) if (b.name.equals(r.name)) has = true;
            if (!has) { build(r.kind, r.tier, r.name); n++; }
        }
        return n;
    }

    void remove(Building b, Workforce wf, Base base) {
        if (b.job != null) stop(b, wf, base);
        release(b, wf);
        buildings.remove(b);
    }

    // ------------------------------------------------------------------ the crew
    /** Is this worker in some building's crew? */
    String busyAt(String workerId) {
        for (Building b : buildings) if (b.crew.contains(workerId)) return b.id;
        return null;
    }

    /** The free workers who can do this recipe (at least its minimum), the best first. */
    List<Worker> candidates(Recipe r, Workforce wf) {
        List<Worker> l = new ArrayList<>();
        for (Worker w : wf.all()) if (busyAt(w.id()) == null && w.skill(r.skill) >= r.min) l.add(w);
        l.sort(Comparator.comparingDouble((Worker w) -> -w.skill(r.skill)).thenComparing(Worker::label));
        return l;
    }

    /** The free workers for a building's upkeep (any skill), the best at its upkeep skill first. */
    List<Worker> upkeepCandidates(Building b, Workforce wf) {
        String sk = b.kind() == null ? "Crafting" : b.kind().upkeep_skill;
        List<Worker> l = new ArrayList<>();
        for (Worker w : wf.all()) if (busyAt(w.id()) == null) l.add(w);
        l.sort(Comparator.comparingDouble((Worker w) -> -w.skill(sk)).thenComparing(Worker::label));
        return l;
    }

    /** The automatic pick (round 1-2): the best free workers for the job's skill fill the free slots. Returns who joined. */
    List<String> pick(Building b, Workforce wf) {
        List<String> got = new ArrayList<>();
        Recipe r = b.job == null ? null : recipe(b.job.recipe);
        List<Worker> c = r != null ? candidates(r, wf) : upkeepCandidates(b, wf);
        int room = (b.site ? Math.max(1, Math.min(99, c.size())) : b.slots()) - b.crew.size();
        if (b.site && r != null) room = Math.max(0, Math.min(c.size(), 4 - b.crew.size()));   // a site job: up to 4 by itself [mine]
        for (Worker w : c) {
            if (room <= 0) break;
            add(b, w, wf);
            got.add(w.label());
            room--;
        }
        return got;
    }

    String activity(Building b) { return "Outside".equals(b.kind) ? "gathering" : "production"; }

    /** One worker into the crew (the players' override). Null when done, else why not. */
    String add(Building b, Worker w, Workforce wf) {
        if (busyAt(w.id()) != null) return w.label() + " already works elsewhere";
        if (!b.site && b.crew.size() >= b.slots()) return b.name + " has no free slot (" + b.slots() + ")";
        Recipe r = b.job == null ? null : recipe(b.job.recipe);
        if (r != null && w.skill(r.skill) < r.min) return w.label() + " is below the minimum: " + r.skill + " " + r.min;
        b.crew.add(w.id());
        wf.assign(w.id(), activity(b));
        return null;
    }

    void drop(Building b, String workerId, Workforce wf) {
        if (b.crew.remove(workerId)) wf.assign(workerId, "");
    }

    void release(Building b, Workforce wf) {
        for (String id : new ArrayList<>(b.crew)) drop(b, id, wf);
    }

    // ------------------------------------------------------------------ jobs
    /**
     * A job in this building: the recipe, how many times (0 = until stopped) and the rarity of the marked inputs. The automatic pick
     * fills the crew. Returns what happened (a "!" first when it could not start).
     */
    String start(Building b, Recipe r, int runs, int rarity, Workforce wf) {
        if (!known(r)) return "! " + (r == null ? "no such recipe" : r.name + " is not known yet (" + (r.research.isEmpty() ? "found" : "research: " + r.research) + ")");
        if (!fits(b, r)) return "! " + b.label() + " cannot make " + r.name + " (a " + r.building + " of Tier " + Rules.roman(r.tier) + " or better)";
        if (b.job != null) return "! " + b.name + " already runs " + recipe(b.job.recipe).name + ": stop it first";
        if (b.condition <= 0) return "! " + b.name + " is broken: its crew must repair it first (upkeep)";
        Job j = new Job();
        j.recipe = r.id;
        j.runs = Math.max(0, runs);
        j.rarity = Math.max(1, Math.min(4, rarity));
        b.job = j;
        // the crew keeps only those who can do it
        for (String id : new ArrayList<>(b.crew)) {
            Worker w = worker(id, wf);
            if (w == null || w.skill(r.skill) < r.min) drop(b, id, wf);
        }
        List<String> got = pick(b, wf);
        return b.name + ": " + r.name + (j.runs == 0 ? " until stopped" : " × " + j.runs) + (got.isEmpty() ? "" : "; the pick: " + String.join(", ", got))
                + (b.crew.isEmpty() ? "; ! nobody free has " + r.skill + " " + r.min : "");
    }

    /** A site job (Base, Outside): its own site, the job started on it. */
    Building startAt(String kind, Recipe r, int runs, int rarity, Workforce wf) {
        Building s = build(kind, 4, kind + ": " + r.name);
        s.site = true;
        String m = start(s, r, runs, rarity, wf);
        if (m.startsWith("!")) { buildings.remove(s); return null; }
        return s;
    }

    /** The job ends: the run's inputs go back to the store (nothing was made of them yet); the crew is free again but for an automatic room's. */
    String stop(Building b, Workforce wf, Base base) {
        if (b.job == null) return "! " + b.name + " has no job";
        Recipe r = recipe(b.job.recipe);
        if (b.job.inputsTaken && r != null) for (Ttr t : r.inputs) if (!t.tool && (!t.extra || b.job.extra))
            base.addUnits(t.type, t.tier, t.sets_rarity ? b.job.rarity : 1, t.count);
        String done = b.name + ": " + (r == null ? "the job" : r.name) + " stopped after " + b.job.done + (b.job.done == 1 ? " run" : " runs");
        b.job = null;
        if (b.kind() == null || !b.kind().automatic) release(b, wf);
        if (b.site) buildings.remove(b);
        return done;
    }

    Worker worker(String id, Workforce wf) {
        for (Worker w : wf.all()) if (w.id().equals(id)) return w;
        return null;
    }

    /**
     * An event hits a building (the GM's: a burst pipe, a fire, a quake; round 6, Marek 11-20: *"The prologue should be full of events"*)
     * [mine]: its condition falls by that many % points. Returns what happened.
     */
    String damage(Building b, double points) {
        double before = b.condition;
        b.condition = Math.max(0, b.condition - Math.max(0, points));
        return b.name + ": condition " + pct(before) + " → " + pct(b.condition) + " %" + (b.condition <= 0 ? ": IT STOPS, its crew must repair it with "
                + UPKEEP_TOOL + " of Tier " + Rules.roman(b.tier) + " or better" : efficiency(b) < 1 ? " (works at " + Math.round(100 * efficiency(b)) + " %)" : "");
    }

    /** A building's upkeep this week: its hours, −20 % with a Quartermaster in the base (02c) [the base's upkeep: mine]. */
    double upkeep(Building b) { return b.upkeepNeed() * (quartermaster ? 0.8 : 1); }

    /**
     * The tool a building's upkeep (and a broken room's repair) needs (round 5, Marek 11-20, verbatim: *"upkeep needs tools of the same
     * tier. So, if there is issue with water filter or reactor, players need to get outside fast."*): the lowest tier of Gear and tools
     * in the store of at least the building's own [at least: mine]. 0 = none.
     */
    static int upkeepTool(Building b, Base base) {
        if (base == null) return 0;
        for (int t = Math.max(1, b.tier); t <= 4; t++) if (base.count(UPKEEP_TOOL, t, 0) > 0) return t;
        return 0;
    }

    /**
     * How well a building works at its condition (round 4, Marek 11-20: *"could be good at the start, since it will get worse as condition
     * worsens."*): full down to 75 %, then down to half at 1 %, and at 0 it stops [the curve mine: 05 §5b's for weapons]. Its power or
     * water made and its crew's work alike.
     */
    static double efficiency(Building b) {
        if (b.condition <= 0) return 0;
        return b.condition >= 75 ? 1 : 0.5 + 0.5 * b.condition / 75;
    }

    // ------------------------------------------------------------------ power and water
    double powerCap() { return produced("power"); }

    double waterCap() { return produced("water"); }

    private double produced(String what) {
        double s = 0;
        for (Building b : buildings) {
            Kind k = b.kind();
            if (k != null && k.automatic && b.condition > 0) s += k.produces.getOrDefault(what, 0.0) * efficiency(b);
        }
        return s;
    }

    /** A building's day: its power and water, once (false = not enough left today: nothing is taken). */
    boolean charge(Building b, Base base) {
        if (b.chargedDay == day) return true;
        Kind k = b.kind();
        double p = k == null ? 0 : k.power, w = k == null ? 0 : k.water + k.water_per_person * Math.max(0, people);
        if (powerUsed + p > powerCap() + 1e-9) return false;
        int tier = drawWater(w, k == null ? "" : k.water_use, base);
        if (tier == 0) return false;
        powerUsed += p;
        b.chargedDay = day;
        b.waterTier = tier;
        if (b.job != null) b.job.water = Math.min(b.job.water, tier);
        return true;
    }

    /**
     * A room's water for the day (round 5, Marek 11-20, verbatim: *"Lower-tier water - yes, agreed."* · *"workshop, kiln, still,
     * scrubbers - I would make it rule that these use T1 water first (reversed priority)."*): a room whose water goes into its product
     * takes the filtration's clean water (Tier III) first, then the store's Water the best tier first; a cooling room the store's Tier I
     * first, then II, the filtration's, III and IV. Returns the worst tier taken (5 = none was needed), or 0 when all of it is not
     * there (then nothing is taken).
     */
    int drawWater(double litres, String use, Base base) {
        if (litres <= 1e-9) return 5;
        double clean = Math.max(0, waterCap() - waterUsed), have = clean;
        if (base != null) for (int t = 1; t <= 4; t++) have += base.count("Water", t, 0);
        if (have + 1e-9 < litres) return 0;
        int[] order = "cooling".equals(use) ? new int[]{1, 2, 0, 3, 4} : new int[]{0, 4, 3, 2, 1};   // 0 = the filtration's clean water
        double left = litres;
        int worst = 5;
        for (int src : order) {
            if (left <= 1e-9) break;
            if (src == 0) {
                double take = Math.min(left, clean);
                if (take > 1e-9) { waterUsed += take; left -= take; worst = Math.min(worst, 3); }
                continue;
            }
            if (base == null) continue;
            int n = Math.min(base.count("Water", src, 0), (int) Math.ceil(left - 1e-9));
            if (n > 0) { base.takeUnits("Water", src, 0, n); left -= n; worst = Math.min(worst, src); }
        }
        return worst;
    }

    /** The washing water's sources: the day's condensate, the filtration's, the store's tiers 1-4. */
    static final int CONDENSATE = 5, FILTRATION = 0;

    /**
     * The order the washing takes its water (round 9) [mine]: the unwounded the least harmful cheap water first (the day's
     * condensate, the store's Tier II, Tier I), then the clean water (the filtration's, the store's Tier III), Tier IV last; the
     * wounded the germ-free water first (Marek 11-21: *"I think germ water is fine without wound."*). Only what the players allow.
     */
    int[] washOrder(boolean hurt) {
        List<Integer> o = new ArrayList<>();
        if (hurt) {
            o.add(FILTRATION); o.add(3);
            if (washTier4) o.add(4);
            if (washTier2) { o.add(CONDENSATE); o.add(2); }
            if (washTier1) o.add(1);
        } else {
            if (washTier2) { o.add(CONDENSATE); o.add(2); }
            if (washTier1) o.add(1);
            o.add(FILTRATION); o.add(3);
            if (washTier4) o.add(4);
        }
        return o.stream().mapToInt(Integer::intValue).toArray();
    }

    /** The condensate of this day not yet used (it goes into the store as Water II after the washing). */
    private transient double condensateLeft;

    /**
     * The people's washing (round 9): {@code litres} by {@link #washOrder}, as much as there is; {@code used[source]} gets the
     * litres taken from each source. Returns the litres got.
     */
    double washFrom(double litres, Base base, boolean hurt, double[] used) {
        double left = litres;
        for (int src : washOrder(hurt)) {
            if (left <= 1e-9) break;
            double take;
            if (src == FILTRATION) {
                take = Math.min(left, Math.max(0, waterCap() - waterUsed));
                waterUsed += take;
            } else if (src == CONDENSATE) {
                take = Math.min(left, condensateLeft);
                condensateLeft -= take;
            } else {
                if (base == null) continue;
                int n = Math.min(base.count("Water", src, 0), (int) Math.ceil(left - 1e-9));
                if (n > 0) base.takeUnits("Water", src, 0, n);
                take = n;
            }
            left -= take;
            if (used != null) used[src] += take;
        }
        return litres - Math.max(0, left);
    }

    /** The people's washing (round 9), everyone as unwounded: kept for the tests and the GM's checks. */
    double washWater(double litres, Base base) { return washFrom(litres, base, false, null); }

    /**
     * Going unwashed (round 9) [the numbers EXAMPLE, mine]: from 3 days Dirty (wound-infection rolls × 1.5), from 7 days Filthy
     * (× 2 and the healing rate −1). The roll's class stays part 4's (a cut 2 %, a gunshot 15 %, a dirty wound or a bite 40 %).
     */
    static double infectionFactor(double days) { return days >= 7 ? 2 : days >= 3 ? 1.5 : 1; }

    static int hygieneHealing(double days) { return days >= 7 ? 1 : 0; }

    static String hygiene(double days) {
        if (days >= 7) return "Filthy (unwashed " + Math.round(days) + " days): wound-infection rolls x2, the healing rate −1";
        if (days >= 3) return "Dirty (unwashed " + Math.round(days) + " days): wound-infection rolls x1.5";
        return "";
    }

    /** Does this building draw its day whether it works or not: the automatic rooms, the kitchen, and a daily one with a job (crops, animals). */
    static boolean everyDay(Building b) {
        Kind k = b.kind();
        return k != null && k.daily && (k.automatic || "Kitchen".equals(b.kind) || b.job != null);
    }

    // ------------------------------------------------------------------ time passes
    /**
     * Hours of the world's time pass (the GM's Pass time for everyone), hour by hour from {@code worldHours}: new days charge the rooms
     * that draw every day (the people's 2 l each first: {@code people}), new weeks check the upkeep, every crew works. Returns what
     * happened, for the GM.
     */
    List<String> advance(double hours, double worldHours, Base base, Workforce wf, int people) {
        return advance(hours, worldHours, base, wf, people, 0);
    }

    /** The same with the wounded among the headcount (round 9: they wash with clean water first). */
    List<String> advance(double hours, double worldHours, Base base, Workforce wf, int people, int wounded) {
        List<String> out = new ArrayList<>();
        this.people = Math.max(0, people);
        this.wounded = Math.max(0, Math.min(this.people, wounded));
        if (hours <= 0) return out;
        Map<String, Worker> byId = new HashMap<>();
        quartermaster = false;
        for (Worker w : wf.all()) { byId.put(w.id(), w); if (w.perk("Quartermaster")) quartermaster = true; }
        double t = worldHours, end = worldHours + hours;
        Map<Building, double[]> missed = new LinkedHashMap<>();   // the condition before, the weeks missed (one line each at the end)
        while (t < end - 1e-9) {
            double dt = Math.min(1, end - t);
            long d = (long) Math.floor(t / 24);
            if (d != day) newDay(d, people, base, out);
            long week = (long) Math.floor(t / 168);
            for (Building b : new ArrayList<>(buildings)) {
                if (b.upkeepWeek != week) {
                    if (b.upkeepWeek >= 0 && upkeep(b) > 0 && b.upkeepDone < upkeep(b) - 1e-9) {
                        double[] m = missed.computeIfAbsent(b, x -> new double[]{x.condition, 0});
                        b.condition = Math.max(0, b.condition - weekWear(b));
                        m[1]++;
                    }
                    b.upkeepWeek = week;
                    b.upkeepDone = 0;
                    b.ranHours = 0;
                }
                hour(b, t, dt, base, wf, byId, out);
            }
            t += dt;
        }
        for (Map.Entry<Building, double[]> e : missed.entrySet()) {
            Building b = e.getKey();
            double before = e.getValue()[0];
            int weeks = (int) e.getValue()[1];
            out.add(b.name + ": upkeep missed " + (weeks == 1 ? "a week" : weeks + " weeks") + ", condition " + pct(before) + " → "
                    + pct(b.condition) + " %" + (b.condition <= 0 ? ": IT STOPS" : before >= 75 && b.condition < 75 ? ": it works less from now" : ""));
        }
        return out;
    }

    /**
     * What a missed week costs (round 6) [EXAMPLE]: its hours of running at the running rate and the rest idle at the idle rate, by the
     * tier, times the share of the week's upkeep not done.
     */
    double weekWear(Building b) {
        double ran = Math.min(168, b.ranHours), share = upkeep(b) <= 0 ? 0 : 1 - Math.min(1, b.upkeepDone / upkeep(b));
        return (ran * wearPerHour(b.tier, true) + (168 - ran) * wearPerHour(b.tier, false)) * share;
    }

    /** A condition for the GM: whole above 10 %, else one decimal (a T IV room loses 0.08 a week). */
    static String pct(double c) {
        double r = Math.round(c * 10) / 10.0;
        return r == Math.rint(r) || c >= 99.95 ? String.valueOf(Math.round(c)) : String.valueOf(r);
    }

    private void newDay(long d, int people, Base base, List<String> out) {
        day = d;
        powerUsed = 0;
        // round 8: the scrubbers give the people's breath and sweat back as Tier II water (no rads, the roll stays) [EXAMPLE]
        // round 9 (Marek 11-21: *"Washing takes the scrubbers' condensed water of the day first" - seems usable.*): the day's
        // condensate serves the washing first, what is left goes into the store
        condensateLeft = 0;
        for (Building b : buildings) {
            Kind k = b.kind();
            if (k == null || k.condensate <= 0 || b.condition <= 0 || base == null) continue;
            double l = k.condensate * Math.max(0, people) * efficiency(b) + b.condensateCarry;
            int n = (int) Math.floor(l + 1e-9);
            b.condensateCarry = Math.max(0, l - n);
            condensateLeft += n;
        }
        double need = DRINK * Math.max(0, people);   // the people drink first (04 §3.9: 2 l a day)
        waterUsed = Math.min(waterCap(), need);
        double rest = need - waterUsed;
        if (rest > 1e-9 && !buildings.isEmpty()) {
            // then the store's Water, the best tier first (round 5); what they drank is the GM's for part 4's harm
            StringJoiner drank = new StringJoiner(", ");
            boolean harm = false;
            for (int t = 4; t >= 1 && rest > 1e-9 && base != null; t--) {
                int n = Math.min(base.count("Water", t, 0), (int) Math.ceil(rest - 1e-9));
                if (n <= 0) continue;
                base.takeUnits("Water", t, 0, n);
                rest -= n;
                drank.add(n + " l of Tier " + Rules.roman(t));
                if (t <= 2) harm = true;
            }
            out.add("Water: the base makes " + Math.round(waterCap()) + " l a day for " + Math.round(need) + " l; the people drank "
                    + (drank.length() == 0 ? "nothing" : drank) + " from the store" + (rest > 1e-9 ? ", " + Math.round(rest) + " l short" : "")
                    + (harm ? " (Tier II water = one harm, Tier I both: 04 §3.9)" : ""));
        }
        // round 9: then they wash (2 l a day each): the wounded first, the players' choice of water; the harm and the shortfall told
        double wash = WASH * Math.max(0, people);
        if (wash > 1e-9 && !buildings.isEmpty()) {
            double[] hurtUsed = new double[6], used = new double[6];
            double hurtNeed = WASH * Math.min(wounded, people);
            double got = washFrom(hurtNeed, base, true, hurtUsed) + washFrom(wash - hurtNeed, base, false, used);
            if (got + 1e-9 < wash) out.add("Washing: " + Math.round(wash - got) + " l short today (" + Math.round(wash) + " l for " + people + " people)");
            out.addAll(washHarm(hurtUsed, used));
            double share = Math.min(1, got / wash);
            unwashed = (1 - share) * (unwashed + 1);
            String h = hygiene(unwashed);
            if (!h.isEmpty()) out.add("The base's people: " + h + " (on average)");
        }
        if (base != null && condensateLeft >= 1 - 1e-9) base.addUnits("Water", 2, 1, (int) Math.floor(condensateLeft + 1e-9));
        condensateLeft = 0;
        for (Building b : buildings)
            if (everyDay(b) && !charge(b, base)) out.add(b.name + ": no power or water for it today");
    }

    /**
     * The harm of the water on the skin (round 9) [the numbers EXAMPLE, mine], for the GM: Tier I a tenth of drinking its rads
     * (+4 a person for dirty water, +10 for irradiated: 04 §3.9's 18 and 48 a litre), the store's Tier II one harm (a boiled
     * water's +4, or a filtered one's germs); a wounded person washed in water with germs gets a wound-infection roll (Tier II at
     * the cut class 2 %, Tier I at the gunshot class 15 %).
     */
    static List<String> washHarm(double[] hurtUsed, double[] used) {
        List<String> out = new ArrayList<>();
        long t1 = Math.round((hurtUsed[1] + used[1]) / WASH), t2 = Math.round((hurtUsed[2] + used[2]) / WASH);
        long hurtGerm2 = Math.round((hurtUsed[2] + hurtUsed[CONDENSATE]) / WASH), hurtGerm1 = Math.round(hurtUsed[1] / WASH);
        if (t1 > 0) out.add("Washing: " + t1 + (t1 == 1 ? " person" : " people") + " washed in Tier I water: +4 rads each (dirty) or +10 (irradiated)");
        if (t2 > 0) out.add("Washing: " + t2 + (t2 == 1 ? " person" : " people") + " washed in the store's Tier II water: +4 rads each if it was boiled, none if filtered");
        if (hurtGerm2 > 0) out.add("Washing: " + hurtGerm2 + " wounded washed in Tier II water: a wound-infection roll at 2 % each (boiled water has no germs)");
        if (hurtGerm1 > 0) out.add("Washing: " + hurtGerm1 + " wounded washed in Tier I water: a wound-infection roll at 15 % each");
        return out;
    }

    private void hour(Building b, double t, double dt, Base base, Workforce wf, Map<String, Worker> byId, List<String> out) {
        b.crew.removeIf(id -> !byId.containsKey(id));   // gone, dead, or no longer working
        if (b.kind() != null && b.kind().automatic && b.condition > 0) b.ranHours += dt;   // it runs round the clock
        Recipe r = b.job == null ? null : recipe(b.job.recipe);
        if (b.job != null && r == null) { b.job = null; return; }
        List<Worker> crew = new ArrayList<>();
        for (String id : b.crew) crew.add(byId.get(id));
        // upkeep first (a week's hours, with a tool of the tier: round 5), then the job; a broken room or one without a job is
        // repaired by its crew [mine]; without the tool the upkeep waits and the crew works the job
        double free = 0;
        boolean foreman = false;
        int tool = upkeep(b) > 0 || b.condition < 100 ? upkeepTool(b, base) : 0;
        b.noTool = upkeep(b) > 0 && b.upkeepDone < upkeep(b) && tool == 0;
        for (Worker w : crew) {
            if (b.upkeepDone < upkeep(b) && tool > 0) {
                b.upkeepDone = Math.min(upkeep(b), b.upkeepDone + dt);
                base.wear(UPKEEP_TOOL, tool, dt);   // 1 % an hour of the work, as a recipe's tool [EXAMPLE]
                continue;
            }
            if (r == null || b.condition <= 0) {
                if (tool > 0 && b.condition < 100) { b.condition = Math.min(100, b.condition + repairPerHour(b.tier) * dt); base.wear(UPKEEP_TOOL, tool, dt); }   // [EXAMPLE]
                continue;
            }
            free += dt * Math.min(4, w.skill(r.skill) / Math.max(1, r.min));
            if (w.perk("Foreman")) foreman = true;
        }
        if (r == null) return;
        if (b.condition <= 0) { b.job.waiting = "broken: the crew repairs it" + (tool == 0 ? " (it needs " + UPKEEP_TOOL + " of Tier " + Rules.roman(b.tier) + " or better)" : ""); return; }
        if (!r.repairs.isEmpty() && !b.job.inputsTaken && base.worn(r.repairs, r.tier, b.job.rarity) == 0) {
            out.add(b.name + ": " + r.name + " done: no worn ones left in that row");
            end(b, wf);
            return;
        }
        if (!b.job.inputsTaken) {
            String miss = takeInputs(b, r, base, t, crew);
            if (miss != null) { b.job.waiting = "needs " + miss; return; }
        }
        if (free > 0 && b.chargedDay != day && !charge(b, base)) { b.job.waiting = "no power or water left today"; return; }
        if (crew.isEmpty() && r.hours > 0 && b.job.work < need(b, r, crew)) { b.job.waiting = "no workers"; return; }
        b.job.waiting = "";
        if (free > 0 && (b.kind() == null || !b.kind().automatic)) b.ranHours += dt;
        b.job.work += free * efficiency(b) * (foreman ? 1.25 : 1) * (b.job.extra ? 1.5 : 1);
        if (b.job.work >= need(b, r, crew) - 1e-9 && t + dt - b.job.startedAt >= r.days * 24 - 1e-9) finish(b, r, base, wf, crew, out);
    }

    /** A recipe that takes found junk apart (Salvager, 02c: *"taking items apart gives +50 % materials"*): Salvage is its only input. */
    static boolean salvage(Recipe r) {
        boolean any = false;
        for (Ttr i : r.inputs) {
            if (i.tool || i.extra) continue;
            if (!"Salvage".equals(i.type)) return false;
            any = true;
        }
        return any;
    }

    /** The run's work in hours at the minimum: Perfectionist twice (02c), Assembly Line half from the second piece on (02c). */
    static double need(Building b, Recipe r, List<Worker> crew) {
        double h = r.hours;
        if (crew.stream().anyMatch(w -> w.perk("Perfectionist"))) h *= 2;
        if (b.job != null && b.job.done > 0 && crew.stream().anyMatch(w -> w.perk("Assembly Line"))) h *= 0.5;
        return h;
    }

    /** The run's inputs out of the store (the marked ones at the job's rarity, the rest the lowest first). Null, or what is missing. */
    String takeInputs(Building b, Recipe r, Base base, double t) { return takeInputs(b, r, base, t, List.of()); }

    String takeInputs(Building b, Recipe r, Base base, double t, List<Worker> crew) {
        if (!r.repairs.isEmpty()) {
            // the repair job: one unit of its material at the parts' tier; Jury Rigging any material of that tier (02c)
            Ttr m = r.inputs.get(0);
            String got = base.count(m.type, m.tier, 0) > 0 ? m.type : null;
            if (got == null && crew.stream().anyMatch(w -> w.perk("Jury Rigging")))
                for (String alt : MATERIALS) if (base.count(alt, m.tier, 0) > 0) { got = alt; break; }
            if (got == null) return "1 " + m.type + " " + Rules.roman(m.tier);
            base.takeUnits(got, m.tier, 0, 1);
            b.job.madeRarity = b.job.rarity;
            b.job.inputsTaken = true;
            b.job.startedAt = t;
            b.job.water = b.chargedDay == day ? b.waterTier : 5;
            return null;
        }
        StringJoiner miss = new StringJoiner(", ");
        for (Ttr i : r.inputs) {
            if (i.extra) continue;
            int have = i.tool ? base.count(i.type, i.tier, 0) : 0;
            if (!i.tool) for (int tt = i.tier; tt <= topTier(r, i); tt++) have += base.count(i.type, tt, wantRarity(b, i));
            if (have < (i.tool ? 1 : i.count)) miss.add(i.count + " " + i.type + " " + Rules.roman(i.tier) + (i.sets_rarity && b.job.rarity > 1 ? " R" + b.job.rarity : ""));
        }
        if (miss.length() > 0) return miss.toString();
        int rarity = 99;
        for (Ttr i : r.inputs) {
            if (i.tool) continue;
            if (i.extra) {
                b.job.extra = base.count(i.type, i.tier, 0) >= i.count && base.takeUnits(i.type, i.tier, 0, i.count) > 0;
                continue;
            }
            int used = 99, left = i.count;
            for (int tt = i.tier; tt <= topTier(r, i) && left > 0; tt++) {   // the exact tier first, then a better Water (round 8)
                int n = Math.min(left, base.count(i.type, tt, wantRarity(b, i)));
                if (n <= 0) continue;
                used = Math.min(used, base.takeUnits(i.type, tt, wantRarity(b, i), n));
                left -= n;
            }
            if (i.sets_rarity) rarity = Math.min(rarity, used);
        }
        b.job.madeRarity = rarity == 99 ? 1 : rarity;
        b.job.inputsTaken = true;
        b.job.startedAt = t;
        b.job.water = b.chargedDay == day ? b.waterTier : 5;
        return null;
    }

    /**
     * The best tier that may stand in for an input (round 8, Marek 11-21, verbatim: *"yes, fix that, but with care. Adding T III water
     * to recipe making T II water from T I would be idiotic."*): a better Water does, the exact tier first; a recipe that makes Water
     * takes none as good as its own product (Boil water Tier I only, Distil water Tier I or II); everything else its own tier.
     */
    static int topTier(Recipe r, Ttr i) {
        if (!"Water".equals(i.type)) return i.tier;
        int top = 4;
        for (Ttr m : r.makes) if ("Water".equals(m.type)) top = Math.min(top, m.tier - 1);
        return Math.max(i.tier, top);
    }

    private static int wantRarity(Building b, Ttr i) { return i.sets_rarity ? b.job.rarity : (i.rarity > 0 ? i.rarity : 0); }

    /** The job is over: the crew free again but for an automatic room's; a site goes. */
    private void end(Building b, Workforce wf) {
        b.job = null;
        if (b.kind() == null || !b.kind().automatic) release(b, wf);
        if (b.site) buildings.remove(b);
    }

    private void finish(Building b, Recipe r, Base base, Workforce wf, List<Worker> crew, List<String> out) {
        Job j = b.job;
        if (!r.repairs.isEmpty()) {
            // the repair job (round 5) [mine, EXAMPLE]: the repair kit's points by the best skill (Mr. Fixit x2) to up to REPAIR.parts worn parts
            double skill = 0;
            for (Worker w : crew) skill = Math.max(skill, w.skill(r.skill));
            double points = Combat.kitRepair(0, skill, crew.stream().anyMatch(w -> w.perk("Mr. Fixit")));
            int n = base.repair(r.repairs, r.tier, j.rarity, points, REPAIR.parts);
            j.done++;
            out.add(b.name + ": " + r.name + " → " + n + (n == 1 ? " part" : " parts") + " +" + Math.round(points) + " % (" + r.skill + " " + Math.round(skill) + ")"
                    + (j.runs > 0 ? " (" + j.done + " of " + j.runs + ")" : ""));
            j.work = 0;
            j.inputsTaken = false;
            j.startedAt = -1;
            if ((j.runs > 0 && j.done >= j.runs) || base.worn(r.repairs, r.tier, j.rarity) == 0) {
                if (j.runs == 0 || j.done < j.runs) out.add(b.name + ": no worn " + r.repairs + " " + Rules.roman(r.tier) + " left: the repair is done");
                end(b, wf);
            }
            return;
        }
        int rarity = j.madeRarity;
        if (crew.stream().anyMatch(w -> w.perk("Master Craftsman"))) rarity++;
        if (crew.stream().anyMatch(w -> w.perk("Perfectionist"))) rarity++;
        rarity = Math.max(1, Math.min(4, rarity));
        StringJoiner made = new StringJoiner(", ");
        if (r.builds != null) {
            Building nb = build(r.builds.kind, r.builds.tier, r.builds.kind);
            made.add("a new " + nb.label());
        }
        // round 5: a room whose water goes into its product makes it no better than the worst water it took
        Kind kd = b.kind();
        int cap = kd != null && "product".equals(kd.water_use) && j.water < 5 ? j.water : 5;
        for (Ttr m : r.makes) {
            double n = m.count;
            int tier = "Water".equals(m.type) ? m.tier : Math.min(m.tier, cap);   // water made is its own input's, not the room's [mine]
            if (r.harvest) n *= harvest / 100 * (crew.stream().anyMatch(w -> w.perk("Good Harvest")) ? 1.5 : 1);
            if ("Chems".equals(m.type) && crew.stream().anyMatch(w -> w.perk("Cook"))) n *= 2;
            if (salvage(r) && crew.stream().anyMatch(w -> w.perk("Salvager"))) n *= 1.5;
            String ck = m.type + "|" + tier;
            double total = n + (j.carry == null ? 0 : j.carry.getOrDefault(ck, 0.0));
            int k = (int) Math.floor(total + 1e-9);
            if (j.carry == null) j.carry = new HashMap<>();
            j.carry.put(ck, Math.max(0, total - k));
            if (k <= 0) continue;
            base.addUnits(m.type, tier, rarity, k);
            made.add(k + " " + m.type + " " + Rules.roman(tier) + " R" + rarity + (tier < m.tier ? " (Tier " + Rules.roman(cap) + " water)" : ""));
        }
        j.water = 5;
        for (Ttr i : r.inputs) if (i.tool) base.wear(i.type, i.tier, Math.max(1, r.hours));   // a tool: 1 % a work hour [EXAMPLE]
        j.done++;
        out.add(b.name + ": " + r.name + " done → " + (made.length() == 0 ? "nothing (the harvest failed)" : made) + (j.runs > 0 ? " (" + j.done + " of " + j.runs + ")" : ""));
        j.work = 0;
        j.inputsTaken = false;
        j.extra = false;
        j.startedAt = -1;
        if (j.runs > 0 && j.done >= j.runs) end(b, wf);
    }

    // ------------------------------------------------------------------ the recipe lists (round 5)
    /** Can the base run this recipe now: anywhere (a site), or in one of its buildings. */
    boolean runnable(Recipe r) {
        if (r == null) return false;
        if (SITES.contains(r.building)) return true;
        for (Building b : buildings) if (!b.site && fits(b, r)) return true;
        return false;
    }

    /**
     * B makes A fully outdated (round 5, Marek 11-20: *"probably hide these fully outdated"*) [the test mine]: at least A's outputs, no
     * input A does not take and none in a greater number, no more hours, days, skill (the same skill), tier, power or water, no input
     * marked for the rarity that A does not mark; and better on at least one count.
     */
    static boolean dominates(Recipe b, Recipe a) {
        if (a == null || b == null || a == b || a.harvest != b.harvest || !a.repairs.isEmpty() || !b.repairs.isEmpty()) return false;
        if ((a.builds == null) != (b.builds == null)) return false;
        if (a.builds != null && (!a.builds.kind.equals(b.builds.kind) || b.builds.tier < a.builds.tier)) return false;
        if (!a.skill.equals(b.skill) || b.min > a.min || b.hours > a.hours + 1e-9 || b.days > a.days + 1e-9 || b.tier > a.tier) return false;
        Kind ka = KINDS.get(a.building), kb = KINDS.get(b.building);
        if (ka != null && kb != null && (kb.power > ka.power + 1e-9 || kb.water > ka.water + 1e-9)) return false;
        int more = 0;
        for (Ttr m : a.makes) {
            int got = 0;
            for (Ttr n : b.makes) if (n.type.equals(m.type) && n.tier == m.tier) got += n.count;
            if (got < m.count) return false;
            if (got > m.count) more++;
        }
        int less = 0;
        for (Ttr i : b.inputs) {
            Ttr same = null;
            for (Ttr j : a.inputs) if (j.type.equals(i.type) && j.tier == i.tier && j.tool == i.tool && j.extra == i.extra) same = j;
            if (same == null || same.count < i.count || (i.sets_rarity && !same.sets_rarity)) return false;
            if (same.count > i.count || (same.sets_rarity && !i.sets_rarity)) less++;
        }
        boolean fewer = b.inputs.size() < a.inputs.size();
        return more > 0 || less > 0 || fewer || b.hours < a.hours - 1e-9 || b.days < a.days - 1e-9 || b.min < a.min || b.tier < a.tier;
    }

    /** The known recipe the base can run that makes this one fully outdated, or null. */
    Recipe outdatedBy(Recipe a) {
        for (Recipe b : RECIPES.values()) if (b != a && known(b) && runnable(b) && dominates(b, a)) return b;
        return null;
    }

    /**
     * Filtered by what they make and what they use (a part of the type's name and tier, "metal ii"), the best first (round 5: *"the best
     * recipes are shown on top"*) [the order mine]: the highest tier made, then the fewest inputs and work hours a unit made, then the
     * lowest skill minimum.
     */
    static List<Recipe> rank(Collection<Recipe> rs, String makes, String uses) {
        String mf = makes == null ? "" : makes.trim().toLowerCase(Locale.ROOT), uf = uses == null ? "" : uses.trim().toLowerCase(Locale.ROOT);
        List<Recipe> l = new ArrayList<>();
        for (Recipe r : rs) {
            boolean mk = mf.isEmpty() || matches(r.makes, mf) || (r.builds != null && ("a " + r.builds.kind).toLowerCase(Locale.ROOT).contains(mf));
            if (mk && (uf.isEmpty() || matches(r.inputs, uf))) l.add(r);
        }
        l.sort(Comparator.comparingInt((Recipe r) -> -madeTier(r, mf)).thenComparingDouble(r -> perUnit(r, mf)).thenComparingInt(r -> r.min)
                .thenComparing(r -> r.name));
        return l;
    }

    static boolean matches(List<Ttr> l, String f) {
        for (Ttr t : l) if ((t.type + " " + Rules.roman(t.tier)).toLowerCase(Locale.ROOT).contains(f)) return true;
        return false;
    }

    /** The highest tier a recipe makes (of the filtered outputs). */
    static int madeTier(Recipe r, String f) {
        if (r.builds != null) return r.builds.tier;
        int t = 0;
        for (Ttr m : r.makes) if (f.isEmpty() || (m.type + " " + Rules.roman(m.tier)).toLowerCase(Locale.ROOT).contains(f)) t = Math.max(t, m.tier);
        return t;
    }

    /** The inputs used up and the work hours, for each unit made (of the filtered outputs). */
    static double perUnit(Recipe r, String f) {
        double cost = r.hours, units = r.builds != null ? 1 : 0;
        for (Ttr i : r.inputs) if (!i.tool && !i.extra) cost += i.count;
        for (Ttr m : r.makes) if (f.isEmpty() || (m.type + " " + Rules.roman(m.tier)).toLowerCase(Locale.ROOT).contains(f)) units += m.count;
        return units <= 0 ? Double.MAX_VALUE : cost / units;
    }

    // ------------------------------------------------------------------ for the menus
    /** One line about a building: its job, crew and state. */
    String status(Building b) {
        StringBuilder sb = new StringBuilder();
        Recipe r = b.job == null ? null : recipe(b.job.recipe);
        sb.append(r == null ? "no job" : r.name + (b.job.runs == 0 ? " (until stopped" : " (" + b.job.done + " of " + b.job.runs) + ", this run "
                + Math.round(100 * Math.min(1, b.job.work / Math.max(0.01, r.hours))) + " %)");
        sb.append(" · crew ").append(b.crew.size()).append(b.site ? "" : "/" + b.slots());
        if (upkeep(b) > 0) sb.append(" · upkeep ").append(SheetGui.f(b.upkeepDone)).append("/").append(SheetGui.f(upkeep(b))).append(" h this week")
                .append(b.noTool ? " (WAITS: it needs " + UPKEEP_TOOL + " of Tier " + Rules.roman(b.tier) + " or better)" : "");
        if (b.condition < 100) sb.append(" · condition ").append(pct(b.condition)).append(" %")
                .append(efficiency(b) < 1 ? " (works at " + Math.round(100 * efficiency(b)) + " %)" : "")
                .append(", repair ").append(SheetGui.f(repairHours(b))).append(" crew h");
        if (b.job != null && !b.job.waiting.isEmpty()) sb.append(" · WAITS: ").append(b.job.waiting);
        return sb.toString();
    }

    /** The crew hours a repair to 100 % still takes (round 7). */
    static double repairHours(Building b) { return Math.max(0, 100 - b.condition) / repairPerHour(b.tier); }

    /** Today's power and water. */
    String supply() {
        return "Power today " + Math.round(powerUsed) + " / " + Math.round(powerCap()) + " · water " + Math.round(waterUsed) + " / " + Math.round(waterCap()) + " l";
    }

    // ------------------------------------------------------------------ the file
    static Production load(Path dataFolder) {
        Path f = dataFolder == null ? null : dataFolder.resolve("production.json");
        Production p = null;
        if (f != null && Files.isRegularFile(f)) {
            try { p = Store.GSON.fromJson(Files.readString(f, StandardCharsets.UTF_8), Production.class); }
            catch (Exception e) {
                try { Files.move(f, f.resolveSibling("production.bad-" + System.currentTimeMillis() + ".json")); } catch (IOException ignored) { }
            }
        }
        if (p == null) p = new Production();
        p.file = f;
        return p;
    }

    void save() {
        if (file == null) return;
        try {
            Files.createDirectories(file.getParent());
            Path tmp = file.resolveSibling("production.json.tmp");
            Files.writeString(tmp, Store.GSON.toJson(this), StandardCharsets.UTF_8);
            Files.move(tmp, file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
        } catch (IOException ignored) { }
    }
}
